require_once __DIR__.'/../server/_core/Database.php';require_once __DIR__.'/../server/_core/Shop.php';
use BYPCMS\Core\{Shop,Database,PaymentGateway};
$root=realpath($argv[1]??'');$c=require $root.'/_storage/config.php';if(!str_contains(str_replace('\\','/',$root),'/outputs/gallery-acceptance/')||$c['database']['host']!=='127.0.0.1'||(int)$c['database']['port']!==3319||empty($c['app']['debug']))throw new RuntimeException('QA only');
$db=new Database($c);$shop=new Shop($db,$c,$root);$n=0;$check=static function($v,$m)use(&$n){if(!$v)throw new RuntimeException($m);$n++;};$throws=static function(callable $f)use($check){try{$f();throw new LogicException('Expected rejection');}catch(RuntimeException $x){$check(true,'rejection');}};
