$s=$shop->settings(true);$shop->configure(array_merge($s,['receipt_enabled'=>true]));$actor=$shop->actor(bin2hex(random_bytes(32)));$shop->changeCart($actor,3,3);$q=$shop->quote($actor,'delivery','WELCOME');$o=$shop->checkout($actor,['name'=>'Receipt Buyer','email'=>'receipt@example.test','phone'=>'+79990000000','address'=>'QA','consent'=>1,'terms'=>1,'shipping'=>'delivery','promo'=>'WELCOME','quote'=>$q['hash'],'token'=>bin2hex(random_bytes(16))]);$control(['next'=>'normal']);$shop->payment($o['reference'],$actor);$p=$db->one('SELECT * FROM byp_shop_payments WHERE order_id=?',[$o['id']]);$body=json_decode($p['body'],true);$receipt=$body['receipt']['items'];$sum=array_sum(array_map(fn($i)=>PaymentGateway::minor($i['amount']['value'])*(int)$i['quantity'],$receipt));$check($sum===(int)$o['total'],'discounted receipt matches payment');
$control(['id'=>$p['provider_id'],'patch'=>['status'=>'succeeded','paid'=>true]]);$shop->payment($o['reference'],$actor);$op=Shop::uuid();$shop->refund((int)$o['id'],0,$op,[0=>1]);$shop->refund((int)$o['id'],0,$op);$returned=(int)$shop->order($o['reference'],$actor)['refunded'];$check($returned===PaymentGateway::minor($receipt[0]['amount']['value']),'fiscal partial refund is based on selected receipt item');$refund=$db->one('SELECT * FROM byp_shop_refunds WHERE operation=?',[$op]);$refundBody=json_decode($refund['body'],true);$check($refundBody['request']['receipt']['items'][0]['quantity']==='1','persisted return receipt uses actual quantity');$throws(fn()=>$shop->refund((int)$o['id'],0,Shop::uuid(),[0=>3]));$throws(fn()=>$shop->refund((int)$o['id'],0,Shop::uuid(),[999=>1]));$shop->refund((int)$o['id'],0,Shop::uuid(),[0=>2,1=>1]);$check($shop->order($o['reference'],$actor)['state']==='refunded','goods and delivery explicitly selected for final fiscal refund');
