$unknown=$db->one('SELECT p.*,o.reference,o.actor,o.total FROM byp_shop_payments p JOIN byp_shop_orders o ON o.id=p.order_id WHERE p.provider_id IS NULL AND o.state="pending" ORDER BY p.id LIMIT 1');$check((bool)$unknown,'unknown attempt fixture');$db->execute('UPDATE byp_shop_payments SET created_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY) WHERE id=?',[$unknown['id']]);$before=$control()['posts'];$throws(fn()=>$shop->payment($unknown['reference'],$unknown['actor']));$check($control()['posts']===$before,'expired unknown operation never creates another payment');$check($db->one('SELECT state FROM byp_shop_payments WHERE id=?',[$unknown['id']])['state']==='review','manual reconciliation visible');$throws(fn()=>$shop->recoverPayment((int)$unknown['order_id'],$p['provider_id']));$remote=null;foreach($control()['payments']as $r)if(($r['metadata']['shop_order']??'')===$unknown['reference'])$remote=$r;$check((bool)$remote,'provider retains original unknown payment');$control(['id'=>$remote['id'],'patch'=>['amount'=>['value'=>PaymentGateway::amount((int)$unknown['total']),'currency'=>'RUB']]]);$shop->recoverPayment((int)$unknown['order_id'],$remote['id']);$check($db->one('SELECT provider_id FROM byp_shop_payments WHERE id=?',[$unknown['id']])['provider_id']===$remote['id'],'verified provider ID safely attached');
